# Diagonal period 5 is fixed by all regular portions of the test: residues 0..4 map to 1,3,5,7,9.
# Preserve the 1/4 frame and the four nonperiodic marks visible in the original clue block.
seq=[1,3,5,7,9]
grid=[]
for r in range(28):
    row=[]
    for c in range(28):
        if r<2 or c<2:
            v=1
        elif r==2 or c==2:
            v=4
        else:
            v=seq[(r+c)%5]
        row.append(v)
    grid.append(row)
for r,c,v in [(3,4,2),(3,5,1),(4,3,2),(5,3,1)]:
    grid[r][c]=v
assert len(grid)==28 and all(len(row)==28 for row in grid)
print(__import__('json').dumps({'action':'submit','grid':grid},separators=(',',':')))

